// Des: Object store interface and S3zz-compatible client (SigV4)
// Flo: sign request > send via transport > check status > put/get/delete/list with paging
// I/O: key + bytes (sync, purge) > bytes or key list; works for B2, R2, Tigris via host + region
// ===================================================================
const std = @import("std"); const base = @import("nt-vend-base.zig"); const s3v4 = @import("sy-clou-s3v4.zig");
const CF = .{ .pagz = 10 };
pub const Objz = struct { key2: []const u8, size: u64 };
pub fn codeErrz(code: u16) anyerror { return if (code == 401 or code == 402 or code == 403) error.CloudDeny else error.CloudHttp; }
pub const Stor = struct { ctx2: *anyopaque, put: *const fn (ctx2: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, key2: []const u8, byt3: []const u8) anyerror!void, get: *const fn (ctx2: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, key2: []const u8) anyerror![]u8, del2: *const fn (ctx2: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, key2: []const u8) anyerror!void, list: *const fn (ctx2: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, pre2: []const u8) anyerror![]Objz };
pub const Pair = struct { akey: []const u8, skey: []const u8 };
pub fn keyzPair(text: []const u8) !Pair { var iter = std.mem.splitScalar(u8, text, '\n'); const akey = std.mem.trim(u8, iter.next() orelse return error.NoKey, " \t\r"); const skey = std.mem.trim(u8, iter.next() orelse return error.NoKey, " \t\r"); if (akey.len == 0 or skey.len == 0) return error.NoKey; return .{ .akey = akey, .skey = skey }; }
pub const S3zz = struct { cred: s3v4.Cred, bukt: []const u8, send: base.Send, gpaz: std.mem.Allocator,
pub fn store(self: *S3zz) Stor { return .{ .ctx2 = self, .put = putz, .get = getz, .del2 = delz, .list = lis3 }; }
fn pathOfzz(self: *S3zz, aren: std.mem.Allocator, key2: []const u8) ![]u8 { var outp: std.ArrayList(u8) = .empty; try outp.append(aren, '/'); try outp.appendSlice(aren, self.bukt); if (key2.len > 0) { var iter = std.mem.splitScalar(u8, key2, '/'); while (iter.next()) |segm| { try outp.append(aren, '/'); try outp.appendSlice(aren, try base.pctzEncz(aren, segm)); } } return outp.toOwnedSlice(aren); }
fn call(self: *S3zz, aren: std.mem.Allocator, iozz: std.Io, meth: []const u8, key2: []const u8, query: []const u8, body: []const u8) !base.Back { const path = try self.pathOfzz(aren, key2); var dbuf: [16]u8 = undefined; const date = try aren.dupe(u8, s3v4.dateNowz(&dbuf, std.Io.Clock.real.now(iozz).toMilliseconds())); const sigz = try s3v4.sigzMake(aren, self.cred, meth, path, query, body, date); const ext2 = try aren.alloc(base.Hdrz, 2); ext2[0] = .{ .name = "x-amz-date", .valu = date }; ext2[1] = .{ .name = "x-amz-content-sha256", .valu = sigz.phsh }; const urlz = try std.fmt.allocPrint(aren, "https://{s}{s}{s}{s}", .{ self.cred.host, path, if (query.len > 0) "?" else "", query }); return self.send.call(self.send.ctx2, self.gpaz, iozz, .{ .post = false, .urlz = urlz, .auth = sigz.auth, .body = body, .meth = meth, .ext2 = ext2 }); }
fn putz(ctx2: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, key2: []const u8, byt3: []const u8) anyerror!void { const self: *S3zz = @ptrCast(@alignCast(ctx2)); const back = try self.call(aren, iozz, "PUT", key2, "", byt3); defer self.gpaz.free(back.body); if (back.code < 200 or back.code >= 300) return codeErrz(back.code); }
fn getz(ctx2: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, key2: []const u8) anyerror![]u8 { const self: *S3zz = @ptrCast(@alignCast(ctx2)); const back = try self.call(aren, iozz, "GET", key2, "", ""); defer self.gpaz.free(back.body); if (back.code < 200 or back.code >= 300) return codeErrz(back.code); return aren.dupe(u8, back.body); }
fn delz(ctx2: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, key2: []const u8) anyerror!void { const self: *S3zz = @ptrCast(@alignCast(ctx2)); const back = try self.call(aren, iozz, "DELETE", key2, "", ""); defer self.gpaz.free(back.body); if (back.code < 200 or back.code >= 300) return codeErrz(back.code); }
fn tagz(srcz: []const u8, from: usize, tag2: []const u8, aren: std.mem.Allocator) !?struct { text: []const u8, endz: usize } { const open = try std.fmt.allocPrint(aren, "<{s}>", .{tag2}); const clos = try std.fmt.allocPrint(aren, "</{s}>", .{tag2}); const begz = std.mem.findPos(u8, srcz, from, open) orelse return null; const endz = std.mem.findPos(u8, srcz, begz + open.len, clos) orelse return null; return .{ .text = srcz[begz + open.len .. endz], .endz = endz + clos.len }; }
fn lis3(ctx2: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, pre2: []const u8) anyerror![]Objz { const self: *S3zz = @ptrCast(@alignCast(ctx2)); var outp: std.ArrayList(Objz) = .empty; var toke: []const u8 = ""; var pag3: usize = 0; while (pag3 < CF.pagz) : (pag3 += 1) { const query = if (toke.len > 0) try std.fmt.allocPrint(aren, "continuation-token={s}&list-type=2&prefix={s}", .{ try base.pctzEncz(aren, toke), try base.pctzEncz(aren, pre2) }) else try std.fmt.allocPrint(aren, "list-type=2&prefix={s}", .{try base.pctzEncz(aren, pre2)}); const back = try self.call(aren, iozz, "GET", "", query, ""); defer self.gpaz.free(back.body); if (back.code < 200 or back.code >= 300) return codeErrz(back.code); const xmlz = try aren.dupe(u8, back.body); var posi: usize = 0; while (try tagz(xmlz, posi, "Contents", aren)) |blkz| { posi = blkz.endz; const key2 = (try tagz(blkz.text, 0, "Key", aren)) orelse continue; const siz2 = (try tagz(blkz.text, 0, "Size", aren)) orelse continue; try outp.append(aren, .{ .key2 = key2.text, .size = std.fmt.parseInt(u64, siz2.text, 10) catch 0 }); } const trun = (try tagz(xmlz, 0, "IsTruncated", aren)) orelse break; if (!std.mem.eql(u8, trun.text, "true")) break; const nxtz = (try tagz(xmlz, 0, "NextContinuationToken", aren)) orelse break; toke = nxtz.text; } return outp.toOwnedSlice(aren); } };
